# React + TypeScript + Vite

This template provides a minimal setup to get React working in Vite with HMR and some ESLint rules.

Currently, two official plugins are available:

- [@vitejs/plugin-react](https://github.com/vitejs/vite-plugin-react/blob/main/packages/plugin-react) uses [Oxc](https://oxc.rs)
- [@vitejs/plugin-react-swc](https://github.com/vitejs/vite-plugin-react/blob/main/packages/plugin-react-swc) uses [SWC](https://swc.rs/)

## React Compiler

The React Compiler is not enabled on this template because of its impact on dev & build performances. To add it, see [this documentation](https://react.dev/learn/react-compiler/installation).

## Expanding the ESLint configuration

If you are developing a production application, we recommend updating the configuration to enable type-aware lint rules:

```js
export default defineConfig([
  globalIgnores(['dist']),
  {
    files: ['**/*.{ts,tsx}'],
    extends: [
      // Other configs...

      // Remove tseslint.configs.recommended and replace with this
      tseslint.configs.recommendedTypeChecked,
      // Alternatively, use this for stricter rules
      tseslint.configs.strictTypeChecked,
      // Optionally, add this for stylistic rules
      tseslint.configs.stylisticTypeChecked,

      // Other configs...
    ],
    languageOptions: {
      parserOptions: {
        project: ['./tsconfig.node.json', './tsconfig.app.json'],
        tsconfigRootDir: import.meta.dirname,
      },
      // other options...
    },
  },
])
```

You can also install [eslint-plugin-react-x](https://github.com/Rel1cx/eslint-react/tree/main/packages/plugins/eslint-plugin-react-x) and [eslint-plugin-react-dom](https://github.com/Rel1cx/eslint-react/tree/main/packages/plugins/eslint-plugin-react-dom) for React-specific lint rules:

```js
// eslint.config.js
import reactX from 'eslint-plugin-react-x'
import reactDom from 'eslint-plugin-react-dom'

export default defineConfig([
  globalIgnores(['dist']),
  {
    files: ['**/*.{ts,tsx}'],
    extends: [
      // Other configs...
      // Enable lint rules for React
      reactX.configs['recommended-typescript'],
      // Enable lint rules for React DOM
      reactDom.configs.recommended,
    ],
    languageOptions: {
      parserOptions: {
        project: ['./tsconfig.node.json', './tsconfig.app.json'],
        tsconfigRootDir: import.meta.dirname,
      },
      // other options...
    },
  },
])
```

"""
BI Agent Tools — كل أداة يستخدمها الوكيل
"""
import io
import json
import base64
import traceback
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np

# ── Tool schemas (for Claude) ──────────────────────────────────────────────────

TOOLS = [
    {
        "name": "analyze_data",
        "description": "Analyze a dataset and return statistics, column info, data types, nulls, and sample rows. Always call this first.",
        "input_schema": {
            "type": "object",
            "properties": {
                "analysis_type": {
                    "type": "string",
                    "enum": ["overview", "correlation", "distribution", "trends", "summary"],
                    "description": "Type of analysis to perform"
                }
            },
            "required": ["analysis_type"]
        }
    },
    {
        "name": "run_python",
        "description": "Execute Python code on the dataset (df is available). Returns stdout output and any errors. Use for custom calculations.",
        "input_schema": {
            "type": "object",
            "properties": {
                "code": {
                    "type": "string",
                    "description": "Python code to execute. 'df' is the loaded DataFrame."
                }
            },
            "required": ["code"]
        }
    },
    {
        "name": "generate_chart",
        "description": "Generate a chart from the dataset and return base64 image.",
        "input_schema": {
            "type": "object",
            "properties": {
                "chart_type": {
                    "type": "string",
                    "enum": ["bar", "line", "pie", "scatter", "heatmap", "histogram", "box"],
                    "description": "Type of chart"
                },
                "x_column": {"type": "string", "description": "Column for X axis"},
                "y_column": {"type": "string", "description": "Column for Y axis (optional for pie/histogram)"},
                "title": {"type": "string", "description": "Chart title in Arabic or English"},
                "color": {"type": "string", "description": "Main color hex e.g. #4f9eff"}
            },
            "required": ["chart_type", "title"]
        }
    },
    {
        "name": "generate_powerbi_code",
        "description": "Generate Power BI DAX measures and M Query code for the dataset.",
        "input_schema": {
            "type": "object",
            "properties": {
                "measures": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "List of business metrics to create e.g. ['Total Sales', 'YoY Growth', 'Customer Count']"
                },
                "language": {"type": "string", "enum": ["ar", "en"], "description": "Output language for comments"}
            },
            "required": ["measures"]
        }
    },
    {
        "name": "generate_tableau_code",
        "description": "Generate Tableau Calculated Fields and data source connection instructions.",
        "input_schema": {
            "type": "object",
            "properties": {
                "calculations": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "List of calculated fields to create"
                },
                "language": {"type": "string", "enum": ["ar", "en"]}
            },
            "required": ["calculations"]
        }
    },
    {
        "name": "generate_report",
        "description": "Generate a structured business report with key findings, recommendations, and KPIs.",
        "input_schema": {
            "type": "object",
            "properties": {
                "language": {"type": "string", "enum": ["ar", "en"], "description": "Report language"},
                "focus": {"type": "string", "description": "Business focus area e.g. 'sales performance', 'customer analysis'"}
            },
            "required": ["language", "focus"]
        }
    }
]


# ── Tool Executor ──────────────────────────────────────────────────────────────

class BIToolExecutor:
    def __init__(self, df: pd.DataFrame):
        self.df = df
        self.charts: list[dict] = []

    def execute(self, tool_name: str, tool_input: dict) -> str:
        try:
            if tool_name == "analyze_data":
                return self._analyze_data(tool_input["analysis_type"])
            elif tool_name == "run_python":
                return self._run_python(tool_input["code"])
            elif tool_name == "generate_chart":
                return self._generate_chart(tool_input)
            elif tool_name == "generate_powerbi_code":
                return self._generate_powerbi(tool_input)
            elif tool_name == "generate_tableau_code":
                return self._generate_tableau(tool_input)
            elif tool_name == "generate_report":
                return self._generate_report(tool_input)
            else:
                return f"Unknown tool: {tool_name}"
        except Exception as e:
            return f"Tool error: {str(e)}\n{traceback.format_exc()}"

    def _analyze_data(self, analysis_type: str) -> str:
        df = self.df
        result = {}

        if analysis_type == "overview":
            result = {
                "shape": {"rows": int(df.shape[0]), "columns": int(df.shape[1])},
                "columns": {col: str(dtype) for col, dtype in df.dtypes.items()},
                "nulls": df.isnull().sum().to_dict(),
                "sample": df.head(3).to_dict(orient="records"),
                "numeric_columns": df.select_dtypes(include=np.number).columns.tolist(),
                "text_columns": df.select_dtypes(include="object").columns.tolist(),
            }
        elif analysis_type == "summary":
            desc = df.describe(include="all")
            result = {"statistics": desc.to_dict()}
        elif analysis_type == "correlation":
            numeric = df.select_dtypes(include=np.number)
            if not numeric.empty:
                result = {"correlation_matrix": numeric.corr().round(3).to_dict()}
            else:
                result = {"error": "No numeric columns for correlation"}
        elif analysis_type == "distribution":
            result = {}
            for col in df.select_dtypes(include=np.number).columns:
                result[col] = {
                    "mean": round(float(df[col].mean()), 2),
                    "median": round(float(df[col].median()), 2),
                    "std": round(float(df[col].std()), 2),
                    "min": round(float(df[col].min()), 2),
                    "max": round(float(df[col].max()), 2),
                }
        elif analysis_type == "trends":
            # Look for date columns
            date_cols = [c for c in df.columns if any(k in c.lower() for k in ["date", "time", "year", "month", "تاريخ", "سنة", "شهر"])]
            if date_cols:
                result["date_columns"] = date_cols
                result["hint"] = "Use run_python to analyze trends over time"
            else:
                result["hint"] = "No obvious date columns found. Columns: " + ", ".join(df.columns.tolist())

        return json.dumps(result, ensure_ascii=False, default=str)

    def _run_python(self, code: str) -> str:
        df = self.df.copy()
        output_buffer = io.StringIO()
        local_vars = {"df": df, "pd": pd, "np": np, "print": lambda *a: output_buffer.write(" ".join(str(x) for x in a) + "\n")}
        try:
            exec(code, {}, local_vars)
            output = output_buffer.getvalue()
            # Capture any new df
            if "result" in local_vars:
                result_val = local_vars["result"]
                if isinstance(result_val, (pd.DataFrame, pd.Series)):
                    output += "\n" + result_val.to_string()
                else:
                    output += "\n" + str(result_val)
            return output or "Code executed successfully (no output)"
        except Exception as e:
            return f"Error: {str(e)}"

    def _generate_chart(self, params: dict) -> str:
        df = self.df
        chart_type = params["chart_type"]
        title = params.get("title", "Chart")
        x_col = params.get("x_column")
        y_col = params.get("y_column")
        color = params.get("color", "#4f9eff")

        # Style
        plt.style.use("dark_background")
        fig, ax = plt.subplots(figsize=(10, 5))
        fig.patch.set_facecolor("#050d1e")
        ax.set_facecolor("#050d1e")
        ax.tick_params(colors="#94a3b8")
        ax.title.set_color("#f1f5f9")
        for spine in ax.spines.values():
            spine.set_edgecolor("#1e3a5f")

        try:
            if chart_type == "bar" and x_col and y_col:
                data = df.groupby(x_col)[y_col].sum().reset_index()
                ax.bar(data[x_col].astype(str), data[y_col], color=color, alpha=0.85)
                ax.set_xlabel(x_col, color="#64748b")
                ax.set_ylabel(y_col, color="#64748b")
            elif chart_type == "line" and x_col and y_col:
                ax.plot(df[x_col].astype(str), df[y_col], color=color, linewidth=2.5, marker="o", markersize=4)
                ax.fill_between(range(len(df)), df[y_col], alpha=0.15, color=color)
                ax.set_xlabel(x_col, color="#64748b")
                ax.set_ylabel(y_col, color="#64748b")
            elif chart_type == "pie" and x_col:
                val_col = y_col if y_col else df.select_dtypes(include=np.number).columns[0]
                data = df.groupby(x_col)[val_col].sum()
                colors_list = [color, "#8b5cf6", "#06b6d4", "#22c55e", "#f59e0b", "#ec4899"]
                ax.pie(data.values, labels=data.index, autopct="%1.1f%%",
                       colors=colors_list[:len(data)], textprops={"color": "#f1f5f9"})
            elif chart_type == "histogram" and x_col:
                ax.hist(df[x_col].dropna(), bins=20, color=color, alpha=0.8, edgecolor="#050d1e")
                ax.set_xlabel(x_col, color="#64748b")
            elif chart_type == "scatter" and x_col and y_col:
                ax.scatter(df[x_col], df[y_col], color=color, alpha=0.6, s=40)
                ax.set_xlabel(x_col, color="#64748b")
                ax.set_ylabel(y_col, color="#64748b")
            elif chart_type == "heatmap":
                numeric = df.select_dtypes(include=np.number)
                sns.heatmap(numeric.corr(), ax=ax, cmap="Blues", annot=True, fmt=".2f",
                            linewidths=0.5, linecolor="#050d1e")
            elif chart_type == "box" and y_col:
                if x_col:
                    groups = [df[df[x_col] == g][y_col].dropna() for g in df[x_col].unique()]
                    ax.boxplot(groups, labels=df[x_col].unique(), patch_artist=True,
                               boxprops=dict(facecolor=color, alpha=0.7))
                else:
                    ax.boxplot(df[y_col].dropna(), patch_artist=True,
                               boxprops=dict(facecolor=color, alpha=0.7))

            ax.set_title(title, fontsize=14, pad=15, color="#f1f5f9")
            plt.tight_layout()

            buf = io.BytesIO()
            plt.savefig(buf, format="png", dpi=150, bbox_inches="tight", facecolor="#050d1e")
            plt.close()
            buf.seek(0)
            img_b64 = base64.b64encode(buf.read()).decode()
            self.charts.append({"title": title, "data": img_b64})
            return json.dumps({"success": True, "chart_index": len(self.charts) - 1, "title": title})
        except Exception as e:
            plt.close()
            return json.dumps({"error": str(e)})

    def _generate_powerbi(self, params: dict) -> str:
        measures = params.get("measures", [])
        lang = params.get("language", "ar")
        df = self.df
        numeric_cols = df.select_dtypes(include=np.number).columns.tolist()
        text_cols = df.select_dtypes(include="object").columns.tolist()

        dax_code = []
        m_query = []

        # M Query - Load Table
        m_query.append(f"""// {'تحميل البيانات' if lang == 'ar' else 'Load Data'}
let
    Source = Excel.Workbook(File.Contents("YOUR_FILE_PATH"), null, true),
    Sheet = Source{{[Item="Sheet1",Kind="Sheet"]}}[Data],
    #"Promoted Headers" = Table.PromoteHeaders(Sheet, [PromoteAllScalars=true]),
    #"Changed Types" = Table.TransformColumnTypes(#"Promoted Headers", {{
        {", ".join([f'{{"{c}", type number}}' for c in numeric_cols[:5]])}
    }})
in
    #"Changed Types\"""")

        # DAX Measures
        for measure in measures:
            m_lower = measure.lower()
            if "total" in m_lower or "sum" in m_lower or "إجمالي" in m_lower:
                col = numeric_cols[0] if numeric_cols else "Value"
                dax_code.append(f"""// {measure}
{measure} =
    SUMX(
        'Table',
        'Table'[{col}]
    )""")
            elif "average" in m_lower or "avg" in m_lower or "متوسط" in m_lower:
                col = numeric_cols[0] if numeric_cols else "Value"
                dax_code.append(f"""// {measure}
{measure} =
    AVERAGEX(
        'Table',
        'Table'[{col}]
    )""")
            elif "count" in m_lower or "عدد" in m_lower:
                dax_code.append(f"""// {measure}
{measure} =
    COUNTROWS('Table')""")
            elif "growth" in m_lower or "نمو" in m_lower:
                col = numeric_cols[0] if numeric_cols else "Value"
                dax_code.append(f"""// {measure} - Year over Year
{measure} =
VAR CurrentValue = SUM('Table'[{col}])
VAR PreviousValue = CALCULATE(SUM('Table'[{col}]), SAMEPERIODLASTYEAR('Table'[Date]))
RETURN
    DIVIDE(CurrentValue - PreviousValue, PreviousValue, 0)""")
            else:
                col = numeric_cols[0] if numeric_cols else "Value"
                dax_code.append(f"""// {measure}
{measure} =
    SUM('Table'[{col}])""")

        result = {
            "m_query": "\n\n".join(m_query),
            "dax_measures": "\n\n".join(dax_code),
            "columns_detected": {"numeric": numeric_cols, "text": text_cols},
            "instructions": {
                "ar": "1. افتح Power BI Desktop\n2. اختر 'Get Data' → 'Excel'\n3. الصق M Query في Advanced Editor\n4. أضف كل DAX Measure في New Measure",
                "en": "1. Open Power BI Desktop\n2. Choose 'Get Data' → 'Excel'\n3. Paste M Query in Advanced Editor\n4. Add each DAX measure via New Measure"
            }[lang]
        }
        return json.dumps(result, ensure_ascii=False, indent=2)

    def _generate_tableau(self, params: dict) -> str:
        calculations = params.get("calculations", [])
        lang = params.get("language", "ar")
        df = self.df
        numeric_cols = df.select_dtypes(include=np.number).columns.tolist()

        fields = []
        for calc in calculations:
            c_lower = calc.lower()
            col = numeric_cols[0] if numeric_cols else "Value"
            if "profit" in c_lower or "ربح" in c_lower:
                fields.append({
                    "name": calc,
                    "formula": f"SUM([{col}]) - SUM([Cost])",
                    "type": "Number"
                })
            elif "ratio" in c_lower or "نسبة" in c_lower:
                fields.append({
                    "name": calc,
                    "formula": f"SUM([{col}]) / TOTAL(SUM([{col}]))",
                    "type": "Number (Percentage)"
                })
            elif "rank" in c_lower or "ترتيب" in c_lower:
                fields.append({
                    "name": calc,
                    "formula": f"RANK(SUM([{col}]))",
                    "type": "Number"
                })
            else:
                fields.append({
                    "name": calc,
                    "formula": f"SUM([{col}])",
                    "type": "Number"
                })

        result = {
            "calculated_fields": fields,
            "columns_available": numeric_cols,
            "instructions": {
                "ar": "1. افتح Tableau Desktop\n2. اتصل بمصدر البيانات\n3. في Data pane، اضغط يمين → Create Calculated Field\n4. الصق الـ formula",
                "en": "1. Open Tableau Desktop\n2. Connect to your data source\n3. In Data pane, right-click → Create Calculated Field\n4. Paste the formula"
            }[lang]
        }
        return json.dumps(result, ensure_ascii=False, indent=2)

    def _generate_report(self, params: dict) -> str:
        lang = params.get("language", "ar")
        focus = params.get("focus", "general")
        df = self.df
        numeric = df.select_dtypes(include=np.number)

        kpis = {}
        for col in numeric.columns[:5]:
            kpis[col] = {
                "total": round(float(numeric[col].sum()), 2),
                "average": round(float(numeric[col].mean()), 2),
                "max": round(float(numeric[col].max()), 2),
                "min": round(float(numeric[col].min()), 2),
            }

        report = {
            "title": f"{'تقرير ذكاء الأعمال' if lang == 'ar' else 'Business Intelligence Report'} — {focus}",
            "dataset_info": {
                "rows": int(df.shape[0]),
                "columns": int(df.shape[1]),
                "columns_list": df.columns.tolist()
            },
            "kpis": kpis,
            "generated_at": pd.Timestamp.now().isoformat(),
        }
        return json.dumps(report, ensure_ascii=False, indent=2)

