"""
AnalystAgent — يحلل البريف ويولّد استراتيجية كاملة
Input:  brief dict (name, services, market, tone, ...)
Output: strategy JSON (positioning, messages, sections, style, copy AR+EN)
"""
import json
import anthropic

ANALYST_SYSTEM = """أنت Strategic Analyst ومتخصص في تحليل العلامات التجارية وبناء استراتيجية المحتوى.

مهمتك: تحليل brief شركة وإنتاج استراتيجية متكاملة تشمل:
1. Brand Positioning — الموقع التنافسي الفريد
2. Target Segments — شرائح الجمهور المستهدف
3. Key Messages — الرسائل الأساسية لكل شريحة
4. Website Sections — قائمة الأقسام مع محتوى كل قسم (عربي + إنجليزي)
5. Style Direction — نظام الألوان، الخطوط، الأسلوب البصري
6. Competitive Edge — ما يميّزهم عن المنافسين

القواعد:
- أنتج JSON نظيفاً فقط، بدون markdown
- النصوص العربية والإنجليزية حقيقية وجاهزة للنشر
- لا placeholder text مطلقاً
- التوصيات مبنية على السوق السعودي
- أسلوب احترافي وموثوق

You are also fluent in English. Brief may be in Arabic or English."""

class AnalystAgent:
    def __init__(self, api_key: str):
        self.client = anthropic.Anthropic(api_key=api_key)

    def analyze(self, brief: dict, on_step=None) -> dict:
        """
        Analyze a company brief and return full strategy.
        brief keys: name, tagline, services[], market, tone, colors_hint, competitors[]
        """
        brief_text = json.dumps(brief, ensure_ascii=False, indent=2)

        prompt = f"""حلّل هذا البريف وأنتج استراتيجية كاملة بصيغة JSON:

{brief_text}

أنتج JSON بالهيكل التالي (بدون أي نص خارج JSON):

{{
  "brand": {{
    "name": "...",
    "tagline_ar": "...",
    "tagline_en": "...",
    "positioning_ar": "جملة تموضع قوية بالعربي",
    "positioning_en": "Strong positioning statement in English",
    "tone": "professional|friendly|bold|minimal"
  }},
  "target_segments": [
    {{
      "name_ar": "...",
      "name_en": "...",
      "pain_ar": "المشكلة التي يعاني منها",
      "pain_en": "Their core pain point",
      "message_ar": "رسالتنا لهم",
      "message_en": "Our message to them"
    }}
  ],
  "style": {{
    "primary_color": "#hex",
    "accent_color": "#hex",
    "bg_color": "#hex",
    "text_color": "#hex",
    "font_ar": "Tajawal|Noto Kufi Arabic",
    "font_en": "Inter|Sora|Plus Jakarta Sans",
    "visual_style": "dark-tech|light-minimal|bold-vibrant|elegant-glass",
    "border_radius": "sharp|rounded|pill",
    "spacing_unit": 4
  }},
  "sections": [
    {{
      "id": "hero",
      "order": 1,
      "type": "hero",
      "content": {{
        "badge_ar": "...", "badge_en": "...",
        "headline_ar": "...", "headline_en": "...",
        "headline_gradient_ar": "الكلمة المميزة", "headline_gradient_en": "Gradient Word",
        "subheadline_ar": "...", "subheadline_en": "...",
        "cta_primary_ar": "...", "cta_primary_en": "...",
        "cta_secondary_ar": "...", "cta_secondary_en": "..."
      }}
    }},
    {{
      "id": "services",
      "order": 2,
      "type": "services_grid",
      "content": {{
        "badge_ar": "خدماتنا", "badge_en": "Our Services",
        "title_ar": "...", "title_en": "...",
        "subtitle_ar": "...", "subtitle_en": "...",
        "items": [
          {{
            "id": "bi-agent",
            "icon": "BarChart3",
            "title_ar": "...", "title_en": "...",
            "desc_ar": "...", "desc_en": "...",
            "features_ar": ["...", "...", "...", "..."],
            "features_en": ["...", "...", "...", "..."],
            "accent": "#hex",
            "badge_ar": "وكيل ذكي", "badge_en": "AI Agent"
          }}
        ]
      }}
    }},
    {{
      "id": "how",
      "order": 3,
      "type": "steps",
      "content": {{
        "badge_ar": "كيف نعمل", "badge_en": "How It Works",
        "title_ar": "...", "title_en": "...",
        "steps": [
          {{"num": 1, "title_ar": "...", "title_en": "...", "desc_ar": "...", "desc_en": "..."}}
        ]
      }}
    }},
    {{
      "id": "stats",
      "order": 4,
      "type": "stats_bar",
      "content": {{
        "items": [
