'use client'
import { motion } from 'framer-motion'
import { BarChart3, Wand2, ArrowLeft, ArrowRight, Sparkles } from 'lucide-react'

interface Props { lang: 'ar' | 'en' }

const t = {
  ar: {
    badge: 'منصة الذكاء الاصطناعي للأعمال',
    title1: 'حوّل بياناتك ومواقعك',
    titleGrad: 'بقوة الذكاء الاصطناعي',
    subtitle: 'INTRSPOT تقدم خدمتين متكاملتين: وكيل BI الذكي لتحليل بياناتك وبناء لوحات التحكم، ووكيل التصميم الإبداعي لبناء مواقعك وعروضك التقديمية — كلاهما بالعربي والإنجليزي.',
    cta1: 'ابدأ مجاناً',
    cta2: 'اكتشف الخدمات',
    pill1: 'وكيل BI الذكي',
    pill2: 'وكيل التصميم',
    stat1v: '100K+', stat1l: 'صف بيانات محللة',
    stat2v: '< 2 min', stat2l: 'وقت التحليل',
    stat3v: '100%', stat3l: 'ثنائي اللغة',
  },
  en: {
    badge: 'AI-Powered Business Platform',
    title1: 'Transform Your Data & Websites',
    titleGrad: 'With AI Intelligence',
    subtitle: 'INTRSPOT delivers two integrated AI services: a BI Agent for data analysis and dashboard building, and a DesignAgent for generating websites and presentations — both fully bilingual Arabic & English.',
    cta1: 'Start Free',
    cta2: 'Explore Services',
    pill1: 'BI Agent',
    pill2: 'Design Agent',
    stat1v: '100K+', stat1l: 'Rows Analyzed',
    stat2v: '< 2 min', stat2l: 'Analysis Time',
    stat3v: '100%', stat3l: 'Bilingual',
  },
}

export default function Hero({ lang }: Props) {
  const c = t[lang]
  const isRTL = lang === 'ar'
  const ArrowIcon = isRTL ? ArrowLeft : ArrowRight

  return (
    <section
      dir={isRTL ? 'rtl' : 'ltr'}
      className="relative min-h-screen flex items-center justify-center overflow-hidden px-4 py-28"
      style={{ background: '#040812' }}
    >
      {/* Background glows */}
      <div className="absolute top-1/4 start-1/4 w-[600px] h-[600px] rounded-full pointer-events-none"
        style={{ background: 'radial-gradient(circle, rgba(14,165,233,0.10) 0%, transparent 70%)' }} />
      <div className="absolute bottom-1/4 end-1/4 w-[500px] h-[500px] rounded-full pointer-events-none"
        style={{ background: 'radial-gradient(circle, rgba(139,92,246,0.09) 0%, transparent 70%)' }} />

      {/* Orbit rings */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <div className="w-[700px] h-[700px] rounded-full border border-white/[0.04] animate-spin" style={{ animationDuration: '30s' }} />
        <div className="absolute w-[500px] h-[500px] rounded-full border border-white/[0.06] animate-spin" style={{ animationDuration: '20s', animationDirection: 'reverse' }} />
      </div>

      <div className="relative z-10 max-w-5xl mx-auto text-center">
        {/* Badge */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-full border border-[#0ea5e9]/30 bg-[#0ea5e9]/10 text-[#0ea5e9] text-sm font-medium mb-8"
        >
          <Sparkles size={14} />
          {c.badge}
        </motion.div>

        {/* Headline */}
        <motion.h1
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7, delay: 0.1 }}
          className="text-4xl sm:text-5xl lg:text-7xl font-bold text-white leading-tight mb-6"
        >
          {c.title1}{' '}
          <span className="bg-gradient-to-r from-[#0ea5e9] to-[#8b5cf6] bg-clip-text text-transparent">
            {c.titleGrad}
          </span>
        </motion.h1>

        {/* Subtitle */}
        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7, delay: 0.2 }}
          className="text-[#94a3b8] text-lg sm:text-xl max-w-3xl mx-auto leading-relaxed mb-10"
        >
          {c.subtitle}
        </motion.p>

        {/* CTAs */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.3 }}
          className="flex flex-wrap items-center justify-center gap-4 mb-14"
        >
          <button className="group flex items-center gap-2 px-8 py-4 rounded-xl font-semibold text-white transition-all duration-300 hover:scale-105 hover:shadow-[0_0_40px_rgba(14,165,233,0.4)]"
            style={{ background: 'linear-gradient(135deg, #0ea5e9, #8b5cf6)' }}>
            {c.cta1}
            <ArrowIcon size={18} className="transition-transform group-hover:translate-x-1" />
          </button>
          <button className="px-8 py-4 rounded-xl font-semibold text-white border border-white/20 bg-white/5 hover:bg-white/10 transition-all duration-300">
            {c.cta2}
          </button>
        </motion.div>

        {/* Service Pills */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.4 }}
          className="flex flex-wrap items-center justify-center gap-4 mb-16"
        >
          <div className="flex items-center gap-2 px-5 py-2.5 rounded-xl border border-[#0ea5e9]/20 bg-[#0ea5e9]/5">
            <BarChart3 size={16} className="text-[#0ea5e9]" />
            <span className="text-white/80 text-sm font-medium">{c.pill1}</span>
          </div>
          <div className="w-px h-4 bg-white/20 hidden sm:block" />
          <div className="flex items-center gap-2 px-5 py-2.5 rounded-xl border border-[#8b5cf6]/20 bg-[#8b5cf6]/5">
            <Wand2 size={16} className="text-[#8b5cf6]" />
            <span className="text-white/80 text-sm font-medium">{c.pill2}</span>
          </div>
        </motion.div>

        {/* Stats bar */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.5 }}
          className="flex flex-wrap justify-center gap-8 sm:gap-16"
        >
          {[
            { v: c.stat1v, l: c.stat1l },
            { v: c.stat2v, l: c.stat2l },
            { v: c.stat3v, l: c.stat3l },
          ].map((s, i) => (
            <div key={i} className="text-center">
              <div className="text-2xl sm:text-3xl font-bold bg-gradient-to-r from-[#0ea5e9] to-[#8b5cf6] bg-clip-text text-transparent">
                {s.v}
              </div>
              <div className="text-[#64748b] text-sm mt-1">{s.l}</div>
            </div>
          ))}
        </motion.div>
      </div>
    </section>
  )
}

