'use client'
import { useState, useEffect } from 'react'
import { Menu, X, Globe } from 'lucide-react'

interface Props {
  lang: 'ar' | 'en'
  onLangChange: (lang: 'ar' | 'en') => void
}

const t = {
  ar: {
    links: [
      { id: 'services', label: 'الخدمات' },
      { id: 'how',      label: 'كيف نعمل' },
      { id: 'pricing',  label: 'الأسعار' },
    ],
    cta: 'ابدأ الآن',
  },
  en: {
    links: [
      { id: 'services', label: 'Services' },
      { id: 'how',      label: 'How It Works' },
      { id: 'pricing',  label: 'Pricing' },
    ],
    cta: 'Get Started',
  },
}

export default function Navbar({ lang, onLangChange }: Props) {
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const c = t[lang]
  const isRTL = lang === 'ar'

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20)
    window.addEventListener('scroll', onScroll)
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  return (
    <nav
      dir={isRTL ? 'rtl' : 'ltr'}
      className={`fixed top-0 inset-x-0 z-50 transition-all duration-300 ${
        scrolled
          ? 'bg-[#040812]/80 backdrop-blur-xl border-b border-white/10 py-3'
          : 'bg-transparent py-5'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 flex items-center justify-between">
        {/* Logo */}
        <a href="#" className="flex items-center gap-2">
          <div className="w-9 h-9 rounded-lg flex items-center justify-center font-bold text-white"
            style={{ background: 'linear-gradient(135deg, #0ea5e9, #8b5cf6)', boxShadow: '0 4px 20px rgba(14,165,233,0.4)' }}>
            I
          </div>
          <span className="text-white font-bold text-xl tracking-tight">INTRSPOT</span>
        </a>

        {/* Desktop links */}
        <div className="hidden md:flex items-center gap-8">
          {c.links.map((link) => (
            <a
              key={link.id}
              href={`#${link.id}`}
              className="text-white/70 hover:text-white text-sm font-medium transition-colors"
            >
              {link.label}
            </a>
          ))}
        </div>

        {/* Desktop actions */}
        <div className="hidden md:flex items-center gap-3">
          {/* Language toggle */}
          <button
            onClick={() => onLangChange(lang === 'ar' ? 'en' : 'ar')}
            className="flex items-center gap-2 px-3 py-2 rounded-lg border border-white/10 bg-white/5 hover:bg-white/10 text-white/80 text-sm font-medium transition-all"
          >
