              <span className="text-white font-bold text-2xl">INTRSPOT</span>
            </div>
            <p className="text-[#94a3b8] text-sm max-w-sm mb-6">
              {c.tagline}
            </p>
            <div className="flex items-center gap-3">
              {[Twitter, Linkedin, Github, Mail].map((Icon, i) => (
                <a
                  key={i}
                  href="#"
                  className="w-9 h-9 rounded-lg border border-white/10 bg-white/5 flex items-center justify-center text-white/60 hover:text-white hover:bg-white/10 transition-all"
                >
                  <Icon size={16} />
                </a>
              ))}
            </div>
          </div>

          {/* Services */}
          <div>
            <h4 className="text-white font-semibold mb-4">{c.services.title}</h4>
            <ul className="space-y-3">
              {c.services.items.map((item, i) => {
                const Icon = item.icon
                return (
                  <li key={i}>
                    <a href="#" className="flex items-center gap-2 text-[#94a3b8] hover:text-white text-sm transition-colors">
                      <Icon size={14} />
                      {item.label}
                    </a>
                  </li>
                )
              })}
            </ul>
          </div>

          {/* Company */}
          <div>
            <h4 className="text-white font-semibold mb-4">{c.company.title}</h4>
            <ul className="space-y-3">
              {c.company.items.map((item, i) => (
                <li key={i}>
                  <a href="#" className="text-[#94a3b8] hover:text-white text-sm transition-colors">
                    {item}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Resources */}
          <div>
            <h4 className="text-white font-semibold mb-4">{c.resources.title}</h4>
            <ul className="space-y-3">
              {c.resources.items.map((item, i) => (
                <li key={i}>
                  <a href="#" className="text-[#94a3b8] hover:text-white text-sm transition-colors">
                    {item}
                  </a>
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Bottom bar */}
        <div className="pt-8 border-t border-white/10 flex flex-col sm:flex-row items-center justify-between gap-4">
          <p className="text-[#64748b] text-sm">{c.legal}</p>
          <p className="text-[#64748b] text-sm">{c.madeIn}</p>
        </div>
      </div>
    </footer>
  )
}

