'use client'
import { useState } from 'react'
import Hero from './components/Hero'
import Services from './components/Services'
import How from './components/How'
import Stats from './components/Stats'
import Pricing from './components/Pricing'
import Cta from './components/Cta'

export default function App() {
  const [lang, setLang] = useState<'ar' | 'en'>('ar')

  return (
    <div
      style={{ background: '#040812', minHeight: '100vh' }}
      dir={lang === 'ar' ? 'rtl' : 'ltr'}
    >
      {/* Lang Toggle */}
      <div className="fixed top-4 end-4 z-50 flex gap-2">
        <button
          onClick={() => setLang('ar')}
          className={`px-3 py-1 rounded-full text-sm font-medium transition-all ${
            lang === 'ar'
              ? 'bg-[#0ea5e9] text-white'
              : 'bg-white/10 text-white/60 hover:bg-white/20'
          }`}
        >
          عربي
        </button>
        <button
          onClick={() => setLang('en')}
          className={`px-3 py-1 rounded-full text-sm font-medium transition-all ${
            lang === 'en'
              ? 'bg-[#0ea5e9] text-white'
              : 'bg-white/10 text-white/60 hover:bg-white/20'
          }`}
        >
          EN
        </button>
      </div>

      <Hero lang={lang} />
        <Services lang={lang} />
        <How lang={lang} />
        <Stats lang={lang} />
        <Pricing lang={lang} />
        <Cta lang={lang} />
    </div>
  )
}

'use client'

import { motion } from 'framer-motion'
import { ArrowRight, Sparkles, CheckCircle2 } from 'lucide-react'

interface CtaProps {
  lang: 'ar' | 'en'
}

export default function Cta({ lang }: CtaProps) {
  const content = {
    ar: {
      title: 'جاهز لتحويل بياناتك وأفكارك إلى واقع؟',
      subtitle: 'ابدأ اليوم مجاناً — بدون بطاقة ائتمانية، بدون التزام، مع إمكانية الوصول الكامل لجميع الميزات لمدة 14 يوماً',
      cta: 'ابدأ تجربتك المجانية',
      note: 'انضم إلى أكثر من 150 شركة سعودية وخليجية تثق في INTRSPOT',
      features: [
        'وصول فوري لجميع الميزات',
        'لا حاجة لبطاقة ائتمانية',
        'دعم فني على مدار الساعة',
        'إلغاء في أي وقت'
      ]
    },
    en: {
      title: 'Ready To Transform Your Data & Ideas Into Reality?',
      subtitle: 'Start today for free — no credit card, no commitment, with full access to all features for 14 days',
      cta: 'Start Your Free Trial',
      note: 'Join 150+ Saudi and GCC companies that trust INTRSPOT',
      features: [
        'Instant access to all features',
        'No credit card required',
        '24/7 technical support',
        'Cancel anytime'
      ]
    }
  }

  const t = content[lang]
  const isRtl = lang === 'ar'

  return (
    <section 
      dir={isRtl ? 'rtl' : 'ltr'} 
      className="relative py-20 md:py-32 overflow-hidden"
      style={{ 
        fontFamily: lang === 'ar' ? 'Noto Kufi Arabic, sans-serif' : 'Inter, sans-serif',
        backgroundColor: '#040812'
      }}
    >
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-[#0ea5e9]/5 to-transparent pointer-events-none" />

      <div className="absolute top-1/4 start-1/4 w-96 h-96 bg-[#0ea5e9]/10 rounded-full blur-3xl" />
      <div className="absolute bottom-1/4 end-1/4 w-96 h-96 bg-[#8b5cf6]/10 rounded-full blur-3xl" />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.6 }}
          className="relative"
        >
          <div className="relative bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl md:rounded-3xl p-8 md:p-12 lg:p-16 overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-br from-[#0ea5e9]/10 via-transparent to-[#8b5cf6]/10" />

            <div className="absolute -top-24 -end-24 w-48 h-48 bg-[#0ea5e9] rounded-full opacity-20 blur-3xl" />
            <div className="absolute -bottom-24 -start-24 w-48 h-48 bg-[#8b5cf6] rounded-full opacity-20 blur-3xl" />

            <div className="relative z-10">
              <motion.div
                initial={{ opacity: 0, scale: 0.9 }}
                whileInView={{ opacity: 1, scale: 1 }}
                viewport={{ once: true }}
                transition={{ delay: 0.2, duration: 0.5 }}
                className="flex justify-center mb-6"
              >
                <div className="inline-flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-[#0ea5e9]/20 to-[#8b5cf6]/20 rounded-full border border-[#0ea5e9]/30">
                  <Sparkles className="w-4 h-4 text-[#0ea5e9]" />
                  <span className="text-sm font-medium text-[#f8fafc]">
                    14 {lang === 'ar' ? 'يوم تجربة مجانية' : 'Days Free Trial'}
                  </span>
                </div>
              </motion.div>

              <motion.h2
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: 0.3, duration: 0.5 }}
                className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold text-center mb-6 leading-tight"
              >
                <span className="bg-gradient-to-r from-[#0ea5e9] via-[#8b5cf6] to-[#0ea5e9] bg-clip-text text-transparent bg-[length:200%_auto] animate-gradient">
                  {t.title}
                </span>
              </motion.h2>

              <motion.p
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: 0.4, duration: 0.5 }}
                className="text-lg md:text-xl text-[#f8fafc]/70 text-center max-w-3xl mx-auto mb-8"
              >
                {t.subtitle}
              </motion.p>

              <motion.div
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: 0.5, duration: 0.5 }}
                className="flex flex-col sm:flex-row items-center justify-center gap-4 mb-10"
              >
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className="group relative px-8 py-4 bg-gradient-to-r from-[#0ea5e9] to-[#8b5cf6] text-white font-semibold rounded-xl overflow-hidden shadow-[0_0_40px_rgba(14,165,233,0.3)] hover:shadow-[0_0_60px_rgba(14,165,233,0.5)] transition-all duration-300"
                >
                  <span className="relative z-10 flex items-center gap-2">
                    {t.cta}
                    <ArrowRight className={`w-5 h-5 transition-transform duration-300 ${isRtl ? 'group-hover:-translate-x-1 rotate-180' : 'group-hover:translate-x-1'}`} />
                  </span>
                  <div className="absolute inset-0 bg-gradient-to-r from-[#8b5cf6] to-[#0ea5e9] opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                </motion.button>
              </motion.div>

              <motion.div
                initial={{ opacity: 0 }}
                whileInView={{ opacity: 1 }}
                viewport={{ once: true }}
                transition={{ delay: 0.6, duration: 0.5 }}
                className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8"
              >
                {t.features.map((feature, index) => (
                  <motion.div
                    key={index}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    transition={{ delay: 0.7 + index * 0.1, duration: 0.4 }}
                    className="flex items-center gap-2 text-sm text-[#f8fafc]/80"
                  >
                    <CheckCircle2 className="w-5 h-5 text-[#0ea5e9] flex-shrink-0" />
                    <span className="leading-tight">{feature}</span>
                  </motion.div>
                ))}
              </motion.div>

              <motion.p
                initial={{ opacity: 0 }}
                whileInView={{ opacity: 1 }}
                viewport={{ once: true }}
                transition={{ delay: 0.9, duration: 0.5 }}
                className="text-center text-[#f8fafc]/60 text-sm"
              >
                {t.note}
              </motion.p>
            </div>
          </div>
        </motion.div>
      </div>

      <style jsx>{`
        @keyframes gradient {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        .animate-gradient {
          animation: gradient 6s ease infinite;
        }
      `}</style>
    </section>
  )
}

'use client'

import { motion } from 'framer-motion'
import { Users, Briefcase, Star, Headphones } from 'lucide-react'

interface StatsProps {
  lang: 'ar' | 'en'
}

export default function Stats({ lang }: StatsProps) {
  const isArabic = lang === 'ar'

  const stats = [
    {
      value: '150+',
      label: isArabic ? 'عميل راضٍ' : 'Happy Clients',
      icon: Users,
    },
    {
      value: '800+',
      label: isArabic ? 'مشروع منجز' : 'Projects Delivered',
      icon: Briefcase,
    },
    {
      value: '98%',
      label: isArabic ? 'نسبة الرضا' : 'Satisfaction Rate',
      icon: Star,
    },
    {
      value: '24/7',
      label: isArabic ? 'دعم مستمر' : '24/7 Support',
      icon: Headphones,
    },
  ]

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15,
        delayChildren: 0.2,
      },
    },
  }

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6,
        ease: [0.22, 1, 0.36, 1],
      },
    },
  }

  return (
    <section
      dir={isArabic ? 'rtl' : 'ltr'}
      className="relative py-16 md:py-20 overflow-hidden"
      style={{
        fontFamily: isArabic ? 'Noto Kufi Arabic, sans-serif' : 'Inter, sans-serif',
