@import "tailwindcss";

@layer base {
  * { box-sizing: border-box; }

  html {
    direction: rtl;
    scroll-behavior: smooth;
  }

  body {
    background-color: #040812;
    color: #e2e8f0;
    font-family: 'Tajawal', 'Segoe UI', sans-serif;
    margin: 0;
    overflow-x: hidden;
  }

  h1, h2, h3, h4, h5, h6 {
    font-family: 'Tajawal', 'Segoe UI', sans-serif;
    font-weight: 700;
    margin: 0;
  }

  p { margin: 0; }

  #root {
    width: 100%;
    min-height: 100vh;
  }
}

@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-18px); }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 20px rgba(14,165,233,0.3); }
  50% { box-shadow: 0 0 60px rgba(14,165,233,0.8), 0 0 100px rgba(139,92,246,0.4); }
}

@keyframes gradient-shift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes rotate-slow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes shimmer {
  0% { transform: translateX(-200%); }
  100% { transform: translateX(200%); }
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

@keyframes slide-up {
  from { opacity: 0; transform: translateY(40px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes particle-drift {
  0% { transform: translateY(100vh) translateX(0); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(-100px) translateX(50px); opacity: 0; }
}

@keyframes scan {
  0% { top: -5%; }
  100% { top: 105%; }
}

.animate-float { animation: float 6s ease-in-out infinite; }
.animate-pulse-glow { animation: pulse-glow 3s ease-in-out infinite; }
.animate-rotate-slow { animation: rotate-slow 20s linear infinite; }
.animate-blink { animation: blink 1s step-end infinite; }

.gradient-text {
  background: linear-gradient(135deg, #0ea5e9, #8b5cf6, #06b6d4);
  background-size: 200% 200%;
  animation: gradient-shift 4s ease infinite;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.gradient-text-2 {
  background: linear-gradient(135deg, #f59e0b, #ec4899, #8b5cf6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.glass {
  background: rgba(8,15,30,0.7);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(14,165,233,0.15);
}

.glass-card {
  background: rgba(8,15,30,0.6);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(14,165,233,0.12);
  transition: all 0.4s cubic-bezier(0.16,1,0.3,1);
}

.glass-card:hover {
  background: rgba(14,165,233,0.06);
  border-color: rgba(14,165,233,0.45);
  transform: translateY(-8px);
  box-shadow: 0 25px 60px rgba(14,165,233,0.18), 0 0 0 1px rgba(14,165,233,0.2);
}

.grid-bg {
  background-image:
    linear-gradient(rgba(14,165,233,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(14,165,233,0.04) 1px, transparent 1px);
  background-size: 60px 60px;
}

.neon-btn {
  background: linear-gradient(135deg, #0ea5e9, #8b5cf6);
  border: none;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
}

.neon-btn::before {
  content: '';
  position: absolute;
  top: 0; left: -100%;
  width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  animation: shimmer 2.5s infinite;
}

.neon-btn:hover {
  box-shadow: 0 0 40px rgba(14,165,233,0.5), 0 0 80px rgba(139,92,246,0.3);
  transform: translateY(-2px);
}

.neon-outline {
  background: transparent;
  border: 1px solid rgba(14,165,233,0.5);
  color: #0ea5e9;
  transition: all 0.3s ease;
}

.neon-outline:hover {
  background: rgba(14,165,233,0.1);
  border-color: #0ea5e9;
  box-shadow: 0 0 20px rgba(14,165,233,0.3), inset 0 0 20px rgba(14,165,233,0.05);
}

.section-reveal {
  opacity: 0;
  transform: translateY(50px);
  transition: all 0.9s cubic-bezier(0.16,1,0.3,1);
}

.section-reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.stat-card {
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 2px;
  background: linear-gradient(90deg, transparent, #0ea5e9, #8b5cf6, transparent);
  animation: shimmer 2s infinite;
}

::-webkit-scrollbar { width: 5px; }
::-webkit-scrollbar-track { background: #040812; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(#0ea5e9, #8b5cf6);
  border-radius: 3px;
}

