import puppeteer from 'puppeteer'
import { mkdir } from 'fs/promises'
import { resolve } from 'path'

const URL = 'http://localhost:5173'
const OUT = resolve('../marketing-exports')
await mkdir(OUT, { recursive: true })

const browser = await puppeteer.launch({
  headless: 'new',
  defaultViewport: null,
  args: ['--no-sandbox', '--disable-setuid-sandbox'],
})

async function capture(name, viewport, task) {
  const page = await browser.newPage()
  await page.setViewport({ ...viewport, deviceScaleFactor: 2 })
  await page.goto(URL, { waitUntil: 'networkidle0', timeout: 60000 })
  // wait for fonts + animations to settle
  await new Promise((r) => setTimeout(r, 1200))
  await task(page)
  await new Promise((r) => setTimeout(r, 600))
  const out = resolve(OUT, name)
  await page.screenshot({ path: out, type: 'png', omitBackground: false })
  console.log(`[OK] ${name}  (${viewport.width}x${viewport.height})`)
  await page.close()
}

// 1) Full-width 1920x1080 — Hero
await capture('01-hero-1920x1080.png', { width: 1920, height: 1080 }, async (p) => {
  await p.evaluate(() => window.scrollTo(0, 0))
})

// 2) Full-width 1920x1080 — Services
await capture('02-services-1920x1080.png', { width: 1920, height: 1080 }, async (p) => {
  await p.evaluate(() => {
    document.getElementById('services')?.scrollIntoView({ block: 'start' })
  })
  await new Promise((r) => setTimeout(r, 500))
  await p.evaluate(() => window.scrollBy(0, -80))
})

// 3) Full-width 1920x1080 — How
await capture('03-how-1920x1080.png', { width: 1920, height: 1080 }, async (p) => {
  await p.evaluate(() => {
    document.getElementById('how')?.scrollIntoView({ block: 'start' })
  })
  await new Promise((r) => setTimeout(r, 500))
  await p.evaluate(() => window.scrollBy(0, -80))
})

// 4) Full-width 1920x1080 — Portfolio (top)
await capture('04-portfolio-1920x1080.png', { width: 1920, height: 1080 }, async (p) => {
  await p.evaluate(() => {
    document.getElementById('portfolio')?.scrollIntoView({ block: 'start' })
  })
  await new Promise((r) => setTimeout(r, 500))
  await p.evaluate(() => window.scrollBy(0, -80))
})

// 5) Full-width 1920x1080 — Pricing
await capture('05-pricing-1920x1080.png', { width: 1920, height: 1080 }, async (p) => {
  await p.evaluate(() => {
    document.getElementById('pricing')?.scrollIntoView({ block: 'start' })
  })
  await new Promise((r) => setTimeout(r, 500))
  await p.evaluate(() => window.scrollBy(0, -80))
})

// 6) Square 1200x1200 — Portfolio Case 01 (analytics)
await capture('06-case-analytics-1200x1200.png', { width: 1200, height: 1200 }, async (p) => {
  await p.evaluate(() => {
    const articles = document.querySelectorAll('#portfolio article')
    // Case 01 is the analytics one (rendered on the right in RTL but second in DOM? Depends on order).
    // We built array so cases[0] = analytics; in DOM order it's first article.
    articles[0]?.scrollIntoView({ block: 'center' })
  })
  await new Promise((r) => setTimeout(r, 500))
})

// 7) Square 1200x1200 — Portfolio Case 02 (design)
await capture('07-case-design-1200x1200.png', { width: 1200, height: 1200 }, async (p) => {
  await p.evaluate(() => {
    const articles = document.querySelectorAll('#portfolio article')
    articles[1]?.scrollIntoView({ block: 'center' })
  })
  await new Promise((r) => setTimeout(r, 500))
})

// 8) LinkedIn banner 1584x396 — Hero top slice
await capture('08-linkedin-banner-1584x396.png', { width: 1584, height: 396 }, async (p) => {
  await p.evaluate(() => window.scrollTo(0, 200))
})

// 9) Twitter/X header 1500x500
await capture('09-twitter-header-1500x500.png', { width: 1500, height: 500 }, async (p) => {
  await p.evaluate(() => window.scrollTo(0, 180))
})

// 10) Full page tall — Portfolio section only
await capture('10-portfolio-full-1440xAuto.png', { width: 1440, height: 2200 }, async (p) => {
  await p.evaluate(() => {
    document.getElementById('portfolio')?.scrollIntoView({ block: 'start' })
  })
  await new Promise((r) => setTimeout(r, 600))
})

// English version — switch lang then capture Portfolio
await capture('11-portfolio-EN-1920x1080.png', { width: 1920, height: 1080 }, async (p) => {
  // click the EN button — its text is "EN"
  const clicked = await p.evaluate(() => {
    const btns = Array.from(document.querySelectorAll('button'))
    const en = btns.find((b) => b.textContent?.trim() === 'EN')
    if (en) { en.click(); return true }
    return false
  })
  await new Promise((r) => setTimeout(r, 700))
  await p.evaluate(() => {
    document.getElementById('portfolio')?.scrollIntoView({ block: 'start' })
  })
  await new Promise((r) => setTimeout(r, 500))
  console.log('   lang switched =', clicked)
})

await browser.close()
console.log(`\nDone. Files saved to: ${OUT}`)

