import { motion } from 'framer-motion'
import { Upload, Cpu, Rocket } from 'lucide-react'

interface HowProps {
  lang: 'ar' | 'en'
}

export default function How({ lang }: HowProps) {
  const isArabic = lang === 'ar'

  const content = {
    badge: isArabic ? 'كيف نعمل' : 'How It Works',
    title: isArabic ? 'من الفكرة إلى المنتج في ثلاث خطوات' : 'From Idea To Product In Three Steps',
    steps: [
      {
        num: 1,
        icon: Upload,
        title: isArabic ? 'ارفع أو اكتب' : 'Upload Or Write',
        desc: isArabic
          ? 'ارفع ملف بياناتك (Excel/CSV) أو اكتب وصفاً لموقعك أو عرضك التقديمي بالعربية أو الإنجليزية'
          : 'Upload your data file (Excel/CSV) or write a description of your website or presentation in Arabic or English'
      },
      {
        num: 2,
        icon: Cpu,
        title: isArabic ? 'الوكيل يعمل' : 'Agent Works',
        desc: isArabic
          ? 'وكلاؤنا الأذكياء يحللون، يصممون، ويبنون منتجك بجودة احترافية — تلقائياً وبدون تدخل بشري'
          : 'Our smart agents analyze, design, and build your product with professional quality — automatically and without human intervention'
      },
      {
        num: 3,
        icon: Rocket,
        title: isArabic ? 'راجع وانشر' : 'Review & Publish',
        desc: isArabic
          ? 'راجع النتائج، اختر التصميم المفضل، وصدّر أو انشر مباشرة على منصتك (Power BI، Tableau، موقعك، أو PPTX)'
          : 'Review results, choose your preferred design, and export or publish directly to your platform (Power BI, Tableau, your website, or PPTX)'
      }
    ]
  }

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1
      }
    }
  }

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6,
        ease: [0.22, 1, 0.36, 1] as const
      }
    }
  }

  return (
    <section
      dir={isArabic ? 'rtl' : 'ltr'}
      className="relative py-20 md:py-32 overflow-hidden"
      style={{ backgroundColor: '#040812' }}
    >
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-[#0ea5e9]/5 to-transparent pointer-events-none" />

      <div className="absolute top-1/4 start-0 w-96 h-96 bg-[#0ea5e9]/10 rounded-full blur-[120px] pointer-events-none" />
      <div className="absolute bottom-1/4 end-0 w-96 h-96 bg-[#8b5cf6]/10 rounded-full blur-[120px] pointer-events-none" />

      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.6 }}
          className="text-center mb-16 md:mb-24"
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.9 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5 }}
            className="inline-block mb-6"
          >
            <span className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/5 backdrop-blur-sm border border-white/10 text-sm font-medium text-[#0ea5e9]">
              <span className="w-2 h-2 rounded-full bg-[#0ea5e9] animate-pulse" />
              {content.badge}
            </span>
          </motion.div>

          <h2
            className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold leading-tight"
            style={{ fontFamily: isArabic ? 'Noto Kufi Arabic, sans-serif' : 'Inter, sans-serif' }}
          >
            <span className="bg-gradient-to-r from-[#0ea5e9] via-[#8b5cf6] to-[#0ea5e9] bg-clip-text text-transparent bg-[length:200%_auto] animate-[gradient_8s_linear_infinite]">
              {content.title}
            </span>
          </h2>
        </motion.div>

        <motion.div
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: '-100px' }}
          className="grid grid-cols-1 md:grid-cols-3 gap-8 lg:gap-12"
        >
          {content.steps.map((step, index) => {
            const Icon = step.icon
            const isMiddle = index === 1

            return (
              <motion.div
                key={step.num}
                variants={itemVariants}
                className="relative group"
              >
                <div className="relative h-full p-8 rounded-2xl bg-white/5 backdrop-blur-sm border border-white/10 hover:border-[#0ea5e9]/50 transition-all duration-500 hover:shadow-[0_0_40px_rgba(14,165,233,0.15)] hover:scale-[1.02]">
                  <div className="absolute -top-6 start-8">
                    <div className="relative">
                      <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-[#0ea5e9] to-[#8b5cf6] flex items-center justify-center text-white font-bold text-lg shadow-[0_0_30px_rgba(14,165,233,0.4)] group-hover:shadow-[0_0_50px_rgba(14,165,233,0.6)] transition-all duration-500">
                        {step.num}
                      </div>
                      <div className="absolute inset-0 rounded-xl bg-gradient-to-br from-[#0ea5e9] to-[#8b5cf6] blur-lg opacity-50 group-hover:opacity-75 transition-opacity duration-500" />
                    </div>
                  </div>

                  {index < content.steps.length - 1 && (
                    <div className="hidden md:block absolute top-1/2 end-0 translate-x-1/2 -translate-y-1/2 z-10">
                      <div className="w-12 h-0.5 bg-gradient-to-r from-[#0ea5e9]/50 to-transparent" />
                      <div className={`absolute top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-[#0ea5e9] ${isArabic ? 'start-0' : 'end-0'} shadow-[0_0_10px_rgba(14,165,233,0.6)]`} />
                    </div>
                  )}

                  <div className="mt-8 mb-6">
                    <div className="w-16 h-16 rounded-xl bg-gradient-to-br from-[#0ea5e9]/20 to-[#8b5cf6]/20 border border-[#0ea5e9]/30 flex items-center justify-center group-hover:scale-110 group-hover:rotate-3 transition-all duration-500">
                      <Icon className="w-8 h-8 text-[#0ea5e9]" strokeWidth={1.5} />
                    </div>
                  </div>

                  <h3
                    className="text-xl md:text-2xl font-bold mb-4 text-white"
                    style={{ fontFamily: isArabic ? 'Noto Kufi Arabic, sans-serif' : 'Inter, sans-serif' }}
                  >
                    {step.title}
                  </h3>

                  <p
                    className="text-slate-300 leading-relaxed text-sm md:text-base"
                    style={{ fontFamily: isArabic ? 'Noto Kufi Arabic, sans-serif' : 'Inter, sans-serif' }}
                  >
                    {step.desc}
                  </p>

                  <div className="absolute inset-0 rounded-2xl bg-gradient-to-br from-[#0ea5e9]/0 via-transparent to-[#8b5cf6]/0 group-hover:from-[#0ea5e9]/5 group-hover:to-[#8b5cf6]/5 transition-all duration-500 pointer-events-none" />
                </div>

                {isMiddle && (
                  <div className="absolute -inset-4 rounded-3xl bg-gradient-to-r from-[#0ea5e9]/20 to-[#8b5cf6]/20 blur-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-700 -z-10" />
                )}
              </motion.div>
            )
          })}
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.6 }}
          className="mt-16 text-center"
        >
          <p
            className="text-slate-400 text-sm md:text-base"
            style={{ fontFamily: isArabic ? 'Noto Kufi Arabic, sans-serif' : 'Inter, sans-serif' }}
          >
            {isArabic
              ? 'جميع الخطوات آلية بالكامل — من التحليل إلى التصميم إلى النشر'
              : 'All steps are fully automated — from analysis to design to publishing'}
          </p>
        </motion.div>
      </div>

      <style>{`
        @keyframes gradient {
          0%, 100% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
        }
      `}</style>
    </section>
  )
}

