import puppeteer from 'puppeteer'
import { resolve } from 'path'

const URL = 'http://localhost:5173'
const OUT = resolve('../marketing-exports')

const browser = await puppeteer.launch({
  headless: 'new',
  defaultViewport: null,
  args: ['--no-sandbox', '--disable-setuid-sandbox'],
})

// Capture each case-study CARD individually at square-ish ratio, then we save as 1200x1200 with padded background.
async function shotCard(index, name) {
  const page = await browser.newPage()
  await page.setViewport({ width: 1600, height: 1600, deviceScaleFactor: 2 })
  await page.goto(URL, { waitUntil: 'networkidle0', timeout: 60000 })
  await new Promise((r) => setTimeout(r, 1000))

  await page.evaluate((i) => {
    const articles = document.querySelectorAll('#portfolio article')
    articles[i]?.scrollIntoView({ block: 'center' })
  }, index)
  await new Promise((r) => setTimeout(r, 800))

  const handle = await page.evaluateHandle((i) => {
    return document.querySelectorAll('#portfolio article')[i]
  }, index)
  const el = handle.asElement()
  if (!el) throw new Error('article not found')

  const out = resolve(OUT, name)
  // Screenshot just that element — its content determines dimensions.
  await el.screenshot({ path: out, type: 'png', omitBackground: false })
  console.log(`[OK] ${name}`)
  await page.close()
}

// Index 0 = analytics (case 01), index 1 = design (case 02)
await shotCard(0, '06-case-analytics-card.png')
await shotCard(1, '07-case-design-card.png')

// Also capture each card in ENGLISH
async function shotCardEN(index, name) {
  const page = await browser.newPage()
  await page.setViewport({ width: 1600, height: 1600, deviceScaleFactor: 2 })
  await page.goto(URL, { waitUntil: 'networkidle0', timeout: 60000 })
  await new Promise((r) => setTimeout(r, 800))

  await page.evaluate(() => {
    const btns = Array.from(document.querySelectorAll('button'))
    const en = btns.find((b) => b.textContent?.trim() === 'EN')
    en?.click()
  })
  await new Promise((r) => setTimeout(r, 700))

  await page.evaluate((i) => {
    const articles = document.querySelectorAll('#portfolio article')
    articles[i]?.scrollIntoView({ block: 'center' })
  }, index)
  await new Promise((r) => setTimeout(r, 700))

  const handle = await page.evaluateHandle((i) => {
    return document.querySelectorAll('#portfolio article')[i]
  }, index)
  const el = handle.asElement()
  const out = resolve(OUT, name)
  await el.screenshot({ path: out, type: 'png', omitBackground: false })
  console.log(`[OK] ${name}`)
  await page.close()
}

await shotCardEN(0, '12-case-analytics-card-EN.png')
await shotCardEN(1, '13-case-design-card-EN.png')

await browser.close()
console.log('\nDone.')

